customCSS:
.t, .history { color: #a0a1a7; }
.join { color: #50a14f; }
.part, .quit { color: #a0a1a7; }
.kick, .error { color: #e45649; }
.notice { color: #c18401; }
.action { color: #a626a4; }
.mode, .nick, .topic, .server { color: #0184bc; }
.highlight { color: #494b53; background-color: #d0d0d0; border-left: 3px solid #a626a4; padding-left: 8px; }
.reply { color: #a0a1a7; border-left: 2px solid #4078f2; padding-left: 6px; }
.oper { color: #fafafa; background-color: #c18401; }
.reactions { color: #4078f2; background-color: #f0f0f0; }
.card { background-color: #f0f0f0; border-color: #a0a1a7; }
.card-title { color: #4078f2; }
.card-desc { color: #a0a1a7; }
.daychange { color: #a0a1a7; border-color: #f0f0f0; }
